  ],
  "claims": [
    {
      "claim": "Alprazolam, a lipophilic tricyclic CNS drug, has reported absolute oral bioavailability of 92% (C04, C15) and 80–100% (C22), with high oral bioavailability and low presystemic extraction (C07); SR formulations show absolute F of 0.84–0.91 (C08, C09, C18, C20), all well above 20%.",
      "card_ids": ["C04","C15","C22","C07","C08","C09","C18","C20"]
    },
    {
      "claim": "Trazodone, a lipophilic basic CNS drug, has reported absolute oral bioavailability of 63–91% across fasted/fed studies (C01, C05, C10, C14), all above 20%.",
      "card_ids": ["C01","C05","C10","C14"]
    },
    {
      "claim": "Triazolam, a structurally related triazolobenzodiazepine with first-pass metabolism, has oral bioavailability estimates of 0.358–0.55 (C12, C16, C21), still above the 20% threshold.",
      "card_ids": ["C12","C16","C21"]
    },
    {
      "claim": "L4 absorption/permeability records for close structural analogs support high intestinal absorption for the query: chlorpromazine 96% human oral absorption (C57), amitriptyline FA 100% (C59), imipramine 100% (C51, C54), amitriptyline HCl freely soluble (C50), and high Caco-2 permeability for pheniramine/chlorpheniramine (C48, C49, C55).",
      "card_ids": ["C57","C59","C51","C54","C50","C48","C49","C55"]
    },
    {
      "claim": "The only low absolute F record (C24, alprazolam in rat, F=0.045) is species-specific and not transferable to human oral bioavailability of the query; it does not provide affirmative evidence for F<20%.",
      "card_ids": ["C24"]
    },
    {
      "claim": "L3 midazolam AUC/Cmax records (C36–C47) are exposure values for a different molecule and do not provide query-specific absolute oral bioavailability evidence.",
      "card_ids": ["C36","C37","C38","C39","C40","C41","C42","C43","C44","C45","C46","C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C48","C49","C50","C51","C52","C53","C54","C55","C56","C57","C58","C59"]
    }
  ],
  "evidence_gaps": [
    "No direct chlorprothixene absolute oral bioavailability record is present.",
    "No IV-comparison or matched oral/reference exposure data for the query molecule.",
    "No first-pass metabolism or systemic clearance data for the query; L4 absorption/permeability records do not quantify systemic F.",
    "No formulation, prandial state, or dose condition is specified for the query.",
    "L4 records are for analog molecules (chlorpromazine, amitriptyline, imipramine, etc.), not the query itself."
  ],
  "decision_summary": "Transferable human absolute-F records for lipophilic basic CNS drugs (alprazolam 92%, trazodone 63–91%, triazolam 36–55%) and L4 absorption/permeability evidence for close analogs (chlorpromazine 96% oral absorption, amitriptyline/imipramine 100% FA) support F≥20%. No affirmative threshold-relevant evidence indicates F<20%; the only low F record is rat-specific alprazolam (C24) with low transferability. Prediction remains high with moderate confidence, and L4 evidence strengthens the absorption component."
}

